mapper.select:
SELECT W.*
FROM shopwizard.tCmpWarehs W

INNER JOIN shopwizard.tCmpShopWarehs SW ON SW.WarehsCode = W.WarehsCode


    AND W.WarehsCode = #{pWarehsCode}
    AND W.WarehsName LIKE CONCAT('%',#{pWarehsName},'%')
    AND SW.ShopCode = #{pShopCode}

ORDER BY W.WarehsCode

LIMIT ${pPageOffset}, ${pPageSize}

SELECT COUNT(*)
FROM shopwizard.tCmpWarehs W

INNER JOIN shopwizard.tCmpShopWarehs SW ON SW.WarehsCode = W.WarehsCode


    AND W.WarehsCode = #{pWarehsCode}
    AND W.WarehsName LIKE CONCAT('%',#{pWarehsName},'%')
    AND SW.ShopCode = #{pShopCode}
